namespace Sace.Api.Tests;

public class ClassificationAndNormalizationTests {
  [Fact] public async Task Carta_318_is_identified_by_filename() => Assert.Equal("CARTA_318",(await Classify("CARTA_318.pdf","")).DocumentTypeCode);
  [Fact] public async Task Carta_318_is_identified_by_pdf_text_and_foundation() { var value=await Classify("documento.pdf","Regla 3.1.8 artículo 36-A Ley Aduanera proveedor importador valor de mercancía"); Assert.Equal("CARTA_318",value.DocumentTypeCode); Assert.Equal("HIGH",value.ConfidenceBand); }
  [Fact] public async Task Incrementables_are_identified() => Assert.Equal("DECLARACION_INCREMENTABLES",(await Classify("gastos.pdf","Declaración de incrementables: flete, seguro y embalaje")).DocumentTypeCode);
  [Fact] public async Task Encomienda_is_identified() => Assert.Equal("CARTA_ENCOMIENDA",(await Classify("carta.pdf","Carta de encomienda del importador al agente aduanal conforme al artículo 59")).DocumentTypeCode);
  [Fact] public async Task Mv_mve_is_identified() => Assert.Equal("MANIFESTACION_VALOR_MV_MVE",(await Classify("MVE.pdf","Manifestación de valor: precio pagado, incrementables y método de valoración")).DocumentTypeCode);
  [Fact] public async Task Ambiguous_document_requires_manual_selection() { var value=await Classify("CARTAS01.pdf",""); Assert.Equal("OTHER",value.DocumentTypeCode); Assert.True(value.RequiresManualSelection); }
  [Fact] public async Task Pdf_without_text_does_not_invent_type() => Assert.Equal("OTHER",(await Classify("scan.pdf","")).DocumentTypeCode);
  [Fact] public async Task Existing_xml_classification_still_works() { var file=File("acuse.xml","<acuse>COVEABC123456</acuse>","application/xml"); var classifier=new DocumentClassifier(new PedimentoXmlParser(),new StubPdfText(""),Config()); Assert.Equal("COVE_ACK",(await classifier.ClassifyAsync(file,default)).DocumentTypeCode); }

  [Theory]
  [InlineData("6,500","6500")]
  [InlineData("6500.00","6500")]
  [InlineData("1.234,50","1234.5")]
  public void Decimal_normalization_is_reproducible(string raw,string expected) => Assert.Equal(expected,new FieldNormalizationService().Normalize(DocumentFieldCodes.Quantity,raw,DocumentFieldDataType.QUANTITY).Value);
  [Theory] [InlineData("usd","USD")] [InlineData("USD","USD")] public void Currency_is_uppercase(string raw,string expected)=>Assert.Equal(expected,new FieldNormalizationService().Normalize(DocumentFieldCodes.Currency,raw,DocumentFieldDataType.CURRENCY).Value);
  [Theory] [InlineData("Piezas","PZA")] [InlineData("PZA","PZA")] public void Units_use_catalog(string raw,string expected)=>Assert.Equal(expected,new FieldNormalizationService().Normalize(DocumentFieldCodes.Quantity,"1",DocumentFieldDataType.QUANTITY,raw).Unit);
  [Fact] public void Pedimento_removes_visual_separators()=>Assert.Equal("264812346000001",new FieldNormalizationService().Normalize(DocumentFieldCodes.PedimentoNumber,"26 48 1234 6-000001",DocumentFieldDataType.IDENTIFIER).Value);
  [Fact] public void Date_is_iso()=>Assert.Equal("2026-10-16",new FieldNormalizationService().Normalize(DocumentFieldCodes.Date,"16/10/2026",DocumentFieldDataType.DATE).Value);
  [Fact] public void Weight_converts_grams_to_kg()=>Assert.Equal(new NormalizedFieldValue("6.5","KG"),new FieldNormalizationService().Normalize(DocumentFieldCodes.GrossWeight,"6500",DocumentFieldDataType.WEIGHT,"g"));

  private static async Task<DocumentClassification> Classify(string name,string text){var classifier=new DocumentClassifier(new PedimentoXmlParser(),new StubPdfText(text),Config());return await classifier.ClassifyAsync(File(name,"%PDF-synthetic","application/pdf"),default);}
  private static IConfiguration Config()=>new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Classification:HighConfidence","0.85"},{"Classification:MediumConfidence","0.60"},{"Classification:FilenameWeight","0.55"},{"Classification:TextSignalWeight","0.22"}}).Build();
  private static IFormFile File(string name,string value,string contentType){var bytes=Encoding.UTF8.GetBytes(value);return new FormFile(new MemoryStream(bytes),0,bytes.Length,"file",name){Headers=new HeaderDictionary(),ContentType=contentType};}
  private sealed class StubPdfText(string value):IPdfTextExtractor { public Task<string> ExtractAsync(Stream stream,CancellationToken ct)=>Task.FromResult(value); }
}

public class CrossValidationEngineTests {
  [Theory]
  [InlineData("6500","6500",CrossComparisonType.EXACT_NUMERIC,CrossValidationOutcome.MATCH)]
  [InlineData("6500","6400",CrossComparisonType.EXACT_NUMERIC,CrossValidationOutcome.MISMATCH)]
  [InlineData("USD","MXN",CrossComparisonType.NORMALIZED_IDENTIFIER,CrossValidationOutcome.MISMATCH)]
  [InlineData("102","100",CrossComparisonType.PERCENT_TOLERANCE,CrossValidationOutcome.MATCH)]
  public async Task Comparable_values_produce_expected_outcome(string source,string target,CrossComparisonType comparison,CrossValidationOutcome expected){await using var fixture=await CrossFixture.Create(source,target,comparison);var rows=await fixture.Engine.ExecuteAsync(fixture.Operation.Id,null,fixture.User.Id);Assert.Equal(expected,Assert.Single(rows).Outcome);Assert.Empty(await fixture.Db.AuditResults.ToListAsync());Assert.Empty(await fixture.Db.Findings.ToListAsync());}
  [Theory]
  [InlineData(MissingEvidenceBehavior.INSUFFICIENT_EVIDENCE,CrossValidationOutcome.INSUFFICIENT_EVIDENCE)]
  [InlineData(MissingEvidenceBehavior.MANUAL_REVIEW,CrossValidationOutcome.MANUAL_REVIEW)]
  [InlineData(MissingEvidenceBehavior.NOT_APPLICABLE,CrossValidationOutcome.NOT_APPLICABLE)]
  public async Task Missing_values_never_create_false_mismatch(MissingEvidenceBehavior behavior,CrossValidationOutcome expected){await using var fixture=await CrossFixture.Create("6500",null,CrossComparisonType.EXACT_NUMERIC,behavior);var result=Assert.Single(await fixture.Engine.ExecuteAsync(fixture.Operation.Id,null,fixture.User.Id));Assert.Equal(expected,result.Outcome);}

  [Fact] public async Task Description_requires_normalized_equality_not_contains(){await using var fixture=await CrossFixture.Create("VÁLVULA INDUSTRIAL","VÁLVULA",CrossComparisonType.NORMALIZED_TEXT);var result=Assert.Single(await fixture.Engine.ExecuteAsync(fixture.Operation.Id,null,fixture.User.Id));Assert.Equal(CrossValidationOutcome.MISMATCH,result.Outcome);}
  [Fact] public async Task Mismatch_does_not_modify_legal_result_or_create_finding(){await using var fixture=await CrossFixture.Create("6500","6400",CrossComparisonType.EXACT_NUMERIC);var audit=new Audit{Number="LEGAL-KEEP",TradeOperationId=fixture.Operation.Id,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=fixture.User.Id};var legal=new AuditResult{Audit=audit,RuleId="LEGAL-KEEP",Outcome=LegalOutcome.COMPLIANT,Status=ResultStatus.Valid,IsIncludedInLegalCompliance=true};fixture.Db.Add(legal);await fixture.Db.SaveChangesAsync();Assert.Equal(CrossValidationOutcome.MISMATCH,Assert.Single(await fixture.Engine.ExecuteAsync(fixture.Operation.Id,audit.Id,fixture.User.Id)).Outcome);fixture.Db.ChangeTracker.Clear();Assert.Equal(LegalOutcome.COMPLIANT,(await fixture.Db.AuditResults.SingleAsync(x=>x.Id==legal.Id)).Outcome);Assert.Empty(await fixture.Db.Findings.ToListAsync());}
  [Fact] public async Task Latest_active_rule_version_is_selected(){await using var fixture=await CrossFixture.Create("6500","6500",CrossComparisonType.EXACT_NUMERIC);var original=await fixture.Db.CrossValidationRules.SingleAsync();fixture.Db.CrossValidationRules.AddRange(Copy(original,2,true),Copy(original,3,false));await fixture.Db.SaveChangesAsync();var result=Assert.Single(await fixture.Engine.ExecuteAsync(fixture.Operation.Id,null,fixture.User.Id));Assert.Equal(2,result.RuleVersion);}
  [Fact] public async Task Trade_operation_fallback_is_identified_as_existing_metadata(){await using var fixture=await CrossFixture.Create("6500",null,CrossComparisonType.EXACT_NUMERIC);fixture.Operation.Quantity=6500;var targetType=await fixture.Db.DocumentTypes.SingleAsync(x=>x.Code=="TARGET");targetType.Code="PEDIMENTO";(await fixture.Db.CrossValidationRules.SingleAsync()).TargetDocumentTypeCode="PEDIMENTO";await fixture.Db.SaveChangesAsync();var result=Assert.Single(await fixture.Engine.ExecuteAsync(fixture.Operation.Id,null,fixture.User.Id));Assert.Equal(CrossValidationOutcome.MATCH,result.Outcome);Assert.Equal(ExtractionMethod.EXISTING_METADATA,result.TargetExtractionMethod);Assert.Contains("no fue extraído del archivo",result.Explanation);}
  [Fact] public async Task Missing_user_is_logged_as_system_without_foreign_key_failure(){await using var fixture=await CrossFixture.Create("6500","6500",CrossComparisonType.EXACT_NUMERIC);await fixture.Engine.ExecuteAsync(fixture.Operation.Id,null,Guid.NewGuid());var logs=await fixture.Db.SystemAuditLogs.Where(x=>x.Action.StartsWith("CROSS_VALIDATION_")).ToListAsync();Assert.Equal(2,logs.Count);Assert.All(logs,x=>Assert.Null(x.UserId));}

  private static CrossValidationRule Copy(CrossValidationRule source,int version,bool active)=>new(){Code=source.Code,Version=version,Name=$"{source.Name} v{version}",Category=source.Category,SourceDocumentTypeCode=source.SourceDocumentTypeCode,SourceFieldCode=source.SourceFieldCode,TargetDocumentTypeCode=source.TargetDocumentTypeCode,TargetFieldCode=source.TargetFieldCode,ComparisonType=source.ComparisonType,PercentTolerance=source.PercentTolerance,MissingEvidenceBehavior=source.MissingEvidenceBehavior,IsActive=active};

  private sealed class CrossFixture : IAsyncDisposable {
    private readonly SqliteConnection connection; public SaceDbContext Db {get;} public TradeOperation Operation {get;} public User User {get;} public ICrossValidationEngine Engine {get;}
    private CrossFixture(SqliteConnection connection,SaceDbContext db,TradeOperation op,User user){this.connection=connection;Db=db;Operation=op;User=user;Engine=new CrossValidationEngine(db,new NoopExtractor());}
    public static async Task<CrossFixture> Create(string source,string? target,CrossComparisonType comparison,MissingEvidenceBehavior behavior=MissingEvidenceBehavior.INSUFFICIENT_EVIDENCE){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Test",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio=$"T-{Guid.NewGuid():N}",PedimentoNumber="26",Period="2026-10",OperationDate=new DateTime(2026,10,1,0,0,0,DateTimeKind.Utc),TariffFraction="1"};var st=new DocumentType{Code="SOURCE",Name="Source"};var tt=new DocumentType{Code="TARGET",Name="Target"};var sd=new OperationDocument{TradeOperation=op,DocumentType=st,OriginalFileName="s.pdf"};var td=new OperationDocument{TradeOperation=op,DocumentType=tt,OriginalFileName="t.pdf"};sd.Fields.Add(new DocumentField{FieldCode=DocumentFieldCodes.Quantity,RawValue=source,NormalizedValue=source,DataType=DocumentFieldDataType.DECIMAL,ExtractionMethod=ExtractionMethod.MANUAL,IsManuallyConfirmed=true,Confidence=.95});if(target is not null)td.Fields.Add(new DocumentField{FieldCode=DocumentFieldCodes.Quantity,RawValue=target,NormalizedValue=target,DataType=DocumentFieldDataType.DECIMAL,ExtractionMethod=ExtractionMethod.MANUAL,IsManuallyConfirmed=true,Confidence=.9});var rule=new CrossValidationRule{Code="TEST-CROSS",Name="Test",Category="Cantidades",SourceDocumentTypeCode="SOURCE",SourceFieldCode=DocumentFieldCodes.Quantity,TargetDocumentTypeCode="TARGET",TargetFieldCode=DocumentFieldCodes.Quantity,ComparisonType=comparison,PercentTolerance=2,MissingEvidenceBehavior=behavior};db.AddRange(user,op,st,tt,sd,td,rule);await db.SaveChangesAsync();return new(connection,db,op,user);}
    public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
  }
  private sealed class NoopExtractor:IDocumentFieldExtractor { public Task<int> ExtractDocumentAsync(Guid documentId,Guid userId,CancellationToken ct=default)=>Task.FromResult(0);public Task<int> ExtractOperationAsync(Guid operationId,Guid userId,CancellationToken ct=default)=>Task.FromResult(0); }
}

public class DocumentFieldExtractionTests {
  [Fact] public async Task Reextraction_replaces_automatic_fields_and_preserves_manual_confirmation(){await using var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Test",Email="fields@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio="FIELDS",PedimentoNumber="26",Period="2026-10",OperationDate=DateTime.UtcNow,TariffFraction="1"};var type=new DocumentType{Code="COMMERCIAL_INVOICE",Name="Factura"};var doc=new OperationDocument{TradeOperation=op,DocumentType=type,OriginalFileName="invoice.pdf",Extension=".pdf",FilePath="synthetic/invoice.pdf",UploadedBy=user.Id};doc.Fields.Add(new DocumentField{FieldCode=DocumentFieldCodes.Description,RawValue="Confirmado",NormalizedValue="CONFIRMADO",DataType=DocumentFieldDataType.TEXT,ExtractionMethod=ExtractionMethod.MANUAL,IsManuallyConfirmed=true});db.AddRange(user,op,type,doc);await db.SaveChangesAsync();var extractor=new DocumentFieldExtractor(db,new StubStorage(),new StubPdfText("Factura: INV-100\nCantidad: 6,500 PZA\nTotal: USD 1250.00\nMoneda: USD"),new FieldNormalizationService());await extractor.ExtractDocumentAsync(doc.Id,user.Id);await extractor.ExtractDocumentAsync(doc.Id,user.Id);var fields=await db.DocumentFields.Where(x=>x.OperationDocumentId==doc.Id).ToListAsync();var manual=Assert.Single(fields,x=>x.IsManuallyConfirmed);var quantity=Assert.Single(fields,x=>x.FieldCode==DocumentFieldCodes.Quantity&&!x.IsManuallyConfirmed);Assert.Equal("Confirmado",manual.RawValue);Assert.Equal(ExtractionMethod.MANUAL,manual.ExtractionMethod);Assert.Equal("6,500",quantity.RawValue);Assert.Equal("6500",quantity.NormalizedValue);Assert.Equal(ExtractionMethod.PDF_TEXT,quantity.ExtractionMethod);Assert.Contains("PDF text",quantity.SourceLocator);}
  [Fact] public async Task PdfPig_returns_controlled_empty_text_for_invalid_pdf(){await using var stream=new MemoryStream("%PDF-invalid"u8.ToArray());Assert.Equal("",await new PdfPigTextExtractor().ExtractAsync(stream,default));}
  private sealed class StubStorage:IFileStorageService { public Task<(string storedName,string relativePath)> SaveAsync(Guid operationId,string documentCode,IFormFile file,CancellationToken ct)=>throw new NotSupportedException();public Task<Stream?> OpenAsync(string relativePath,CancellationToken ct)=>Task.FromResult<Stream?>(new MemoryStream("%PDF-synthetic"u8.ToArray())); }
  private sealed class StubPdfText(string value):IPdfTextExtractor { public Task<string> ExtractAsync(Stream stream,CancellationToken ct)=>Task.FromResult(value); }
}

public class MonthlyAuditMetricTests {
  [Fact] public async Task Monthly_metrics_count_only_audited_operations_once(){await using var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();await using var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var imp=Op("IMP","40169304",OperationType.Importacion,true,2);var exp=Op("EXP","40169304",OperationType.Exportacion,true,1);var other=Op("OTHER","99999999",OperationType.Importacion,false,0);var outside=Op("OUT","88888888",OperationType.Exportacion,true,1,"2026-09");db.AddRange(imp,exp,other,outside);await db.SaveChangesAsync();var json=JsonSerializer.Serialize(await new DemoMonthlyConsolidationRule(db).EvaluateAsync("2026-10",default));using var doc=JsonDocument.Parse(json);var root=doc.RootElement;Assert.Equal(2,root.GetProperty("auditedOperations").GetInt32());Assert.Equal(1,root.GetProperty("imports").GetInt32());Assert.Equal(1,root.GetProperty("exports").GetInt32());Assert.Equal(1,root.GetProperty("distinctTariffFractions").GetInt32());Assert.Equal(2,root.GetProperty("tariffFractions")[0].GetProperty("total").GetInt32());}
  private static TradeOperation Op(string folio,string fraction,OperationType type,bool audited,int audits,string period="2026-10"){var op=new TradeOperation{Folio=folio,PedimentoNumber=folio,Period=period,OperationDate=new DateTime(2026,10,1,0,0,0,DateTimeKind.Utc),TariffFraction=fraction,OperationType=type};if(audited)for(var i=0;i<audits;i++)op.Audits.Add(new Audit{Number=$"{folio}-{i}",AuditType=AuditType.Daily,Status=AuditStatus.Completed,CreatedBy=Guid.NewGuid()});return op;}
}
